export interface ConnectorConfig {
  asanaAccessToken: string
  workspaceGid: string
  fetch?: typeof fetch
}

export interface JotformSubmission {
  first_name?: string
  last_name?: string
  email?: string
  company?: string
  answers: Record<string, string>
}

export interface HandleResult {
  taskGid: string
  taskName: string
}

function buildTaskName(submission: JotformSubmission): string {
  const parts: string[] = []
  if (submission.first_name) parts.push(submission.first_name)
  if (submission.last_name) parts.push(submission.last_name)
  if (submission.company) parts.push(submission.company)
  return parts.length > 0 ? parts.join(' ') : 'Jotform Submission'
}

function buildNotes(submission: JotformSubmission): string {
  const lines: string[] = []
  for (const [question, answer] of Object.entries(submission.answers)) {
    lines.push(`${question}: ${answer}`)
  }
  return lines.join('\n')
}

export async function handle(
  payload: JotformSubmission,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.answers || Object.keys(payload.answers).length === 0) {
    throw new Error('Missing required field: answers')
  }

  const fetchImpl = config.fetch ?? fetch
  const taskName = buildTaskName(payload)
  const notes = buildNotes(payload)

  const requestBody = {
    data: {
      name: taskName.slice(0, 255),
      notes,
      workspace: config.workspaceGid,
    },
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Asana API error: ${response.status} ${response.statusText} at POST https://app.asana.com/api/1.0/tasks`)
  }

  const result = (await response.json()) as { data: { gid: string; name: string } }
  return {
    taskGid: result.data.gid,
    taskName: result.data.name,
  }
}

import { describe, it, expect, vi } from 'vitest'
