import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token',
      workspaceGid: '1234567890123456',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.taskGid).toBe('9876543210987654')
    expect(result.taskName).toBe('John Doe Acme Corp')
