describe('handle', () => {
  it('maps fields correctly and calls Asana with expected body', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) =>
      req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST'
        ? jsonResponse(TARGET_ENDPOINTS[0].response, 201)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: JotformSubmission = {
      first_name: 'Jane',
      last_name: 'Smith',
      email: 'jane@example.com',
      company: 'Globex',
      answers: {
        'What is your name?': 'Jane Smith',
        'What is your email?': 'jane@example.com',
        'What company do you work for?': 'Globex',
      },
    }

    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token-123',
      workspaceGid: '999888777666555',
      fetch,
    }

    const result = await handle(payload, config)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://app.asana.com/api/1.0/tasks')
    expect(call.headers.get('authorization')).toBe('Bearer test-token-123')
    expect(call.json).toEqual({
      data: {
        name: 'Jane Smith Globex',
        notes: 'What is your name?: Jane Smith\nWhat is your email?: jane@example.com\nWhat company do you work for?: Globex',
        workspace: '999888777666555',
      },
    })
    expect(result.taskGid).toBe('9876543210987654')
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response, 201))
    const config: ConnectorConfig = {
      asanaAccessToken: 'token',
      workspaceGid: 'ws-1',
      fetch,
    }
    await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBe(1)
  })

  it('throws when answers field is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { first_name: 'John' } as unknown as JotformSubmission
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: answers')
  })

  it('throws when answers is empty object', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: JotformSubmission = { answers: {} }
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: answers')
  })

  it('throws descriptive error on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ errors: [{ message: 'Unauthorized' }] }, 401))
    const config: ConnectorConfig = { asanaAccessToken: 'bad-token', workspaceGid: 'ws', fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)).rejects.toThrow(
      'Asana API error: 401 Unauthorized at POST https://app.asana.com/api/1.0/tasks'
    )
    expect(calls.length).toBe(1)
  })

  it('truncates task name to 255 characters', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      const body = req.json as { data: { name: string } }
      expect(body.data.name.length).toBeLessThanOrEqual(255)
      return jsonResponse(TARGET_ENDPOINTS[0].response, 201)
    })
    const longName = 'a'.repeat(300)
    const payload: JotformSubmission = {
      first_name: longName,
      answers: { q: 'a' },
    }
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }
    await handle(payload, config)
  })

  it('builds task name from available fields only', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response, 201))
    const payload: JotformSubmission = {
      first_name: 'OnlyFirst',
      answers: { q: 'a' },
    }
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }
    await handle(payload, config)
    expect((calls[0].json as { data: { name: string } }).data.name).toBe('OnlyFirst')
  })

  it('uses default name when no name fields provided', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response, 201))
    const payload: JotformSubmission = {
      answers: { q: 'a' },
    }
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }
    await handle(payload, config)
    expect((calls[0].json as { data: { name: string } }).data.name).toBe('Jotform Submission')
  })
})

